// Deterministic hit timing, visible damage, progressive cheek sprites and a rescue ending.
const combatSheet=new Image();let combatReady=false;combatSheet.onload=()=>combatReady=true;combatSheet.src='assets/vy-combat-red-cheeks.webp';
let playerHP=100,cheekLevel=0,combatHits=0,combatResult='fight',combatTimer=1.25,combatInit=false,pendingPunch=null,punchAge=99,combatCooldown=0,playerHurt=0,bossHurt=0,attackLanded=false,rescueTime=0,rescueNote=-1,damageTexts=[],bossAttackAge=99;
const beforeCombatStart=start,beforeCombatFrame=frame,beforeCombatDraw=draw,beforeCombatMove=move,beforeCombatAct=act,beforeCombatFinish=finish;
const retryBossButton=document.createElement('button');retryBossButton.className='secondary';retryBossButton.textContent='Tái đấu Răng Khôn ↻';retryBossButton.hidden=true;retryBossButton.style.margin='20px';retryBossButton.onclick=()=>retryBoss();$('finish').append(retryBossButton);
function resetCombat(){playerHP=100;cheekLevel=combatHits=0;duelHP=100;duelClock=0;duelPhase='intro';combatResult='fight';combatTimer=1.25;combatInit=false;pendingPunch=null;punchAge=99;combatCooldown=0;playerHurt=bossHurt=0;attackLanded=false;rescueTime=0;rescueNote=-1;damageTexts=[];bossAttackAge=99;guardUntil=dodgeUntil=0;epilogue=-1;bossWon=false;$('right').hidden=false;retryBossButton.hidden=true}
start=function(){resetCombat();beforeCombatStart()};
function initCombat(){combatInit=true;duelStarted=true;objects=[];rain=flood=0;stopClip();$('chapter').textContent='CHƯƠNG 03 / ĐẤU TRƯỜNG RĂNG KHÔN';$('chapterTitle').textContent='Vy vs. Răng Khôn';$('instruction').textContent='Đánh thường −10 · Phản công lúc sơ hở −25 · ← Né · → Đỡ';$('left').textContent='Né ↶';$('right').textContent='Đỡ ◇';$('controls').hidden=false;toast('Đòn nào cũng có sát thương. Chờ lúc boss sơ hở để đánh mạnh hơn!',3.5)}
function retryBoss(){cancelAnimationFrame(raf);stopClip();mode=2;lateEnding=-1;endingKind='escape';distance=1170;playing=true;paused=false;last=0;$('game').hidden=false;$('finish').hidden=true;$('pauseOverlay').hidden=true;$('pause').textContent='Tạm dừng Ⅱ';resetCombat();raf=requestAnimationFrame(frame);window.scrollTo({top:0,behavior:'smooth'})}
move=function(d){if(mode!==2||lateEnding>=0){beforeCombatMove(d);return}if(!playing||paused||combatResult==='win')return;if(combatResult==='lost'){if(d<0)retryBoss();return}if(duelPhase==='intro')return;if(d<0){dodgeUntil=duelClock+1.45;beep(340,.08)}else{guardUntil=duelClock+1.6;beep(260,.08)}};
act=function(){if(mode!==2||lateEnding>=0){beforeCombatAct();return}if(!playing||paused)return;if(combatResult==='lost'){rescueTime=Math.max(9,rescueTime);return}if(combatResult!=='fight'||duelPhase==='intro'||combatCooldown>0||pendingPunch)return;combatCooldown=.6;punchAge=0;pendingPunch={remaining:.18};beep(480,.08)};
$('action').onclick=()=>act();$('left').onclick=()=>move(-1);$('right').onclick=()=>move(1);
function hurtBoss(){const amount=duelPhase==='open'?25:10;duelHP=Math.max(0,duelHP-amount);bossHurt=.32;damageTexts.push({side:'boss',text:'−'+amount,age:0,color:amount===25?'#ffe29f':'#f8ead7'});beep(amount===25?820:590,.12);if(duelHP===0){combatResult='win';bossWon=true;epilogue=0;pendingPunch=null;$('controls').hidden=true;$('chapter').textContent='THE FINAL SCENE / CHỈ CẦN THẢ LỎNG';$('chapterTitle').textContent='Đã tiễn một chiếc răng. Đến giờ sinh nhật!';$('bubble').hidden=true}else if(amount===25){duelPhase='recover';combatTimer=.7;toast('Phản công trúng! −25. Răng khôn đang choáng.',1.4)}}
function hurtPlayer(){if(attackLanded)return;attackLanded=true;if(duelClock<dodgeUntil){damageTexts.push({side:'player',text:'NÉ ĐẸP',age:0,color:'#b8ece1'});guardCount++;beep(790,.1);return}if(duelClock<guardUntil){damageTexts.push({side:'player',text:'ĐỠ · 0',age:0,color:'#b8ece1'});guardCount++;beep(680,.1);return}playerHP=Math.max(0,playerHP-25);combatHits++;bossHits++;cheekLevel=Math.min(3,combatHits);playerHurt=.5;damageTexts.push({side:'player',text:'−25 · MÁ SƯNG +1',age:0,color:'#ffb5a4'});beep(145,.18);if(!playerHP){combatResult='lost';pendingPunch=null;rescueTime=0;endingKind='boss-rest';$('chapterTitle').textContent='Thua hiệp đấu. Không mất phần sinh nhật.';$('instruction').textContent='Vy được quyền nghỉ. Tái đấu ngay hoặc xem đoạn kết tiếp tế.';$('left').textContent='Tái đấu ↻';$('action').textContent='Xem tiếp ♥';$('right').hidden=true;$('bubble').hidden=true}else toast(`Trúng đòn: −25 thể lực. Má sưng mức ${cheekLevel}/3 — né hoặc đỡ nhé!`,2)}
frame=function(t){if(mode!==2||lateEnding>=0||combatResult==='win'){beforeCombatFrame(t);return}if(!playing)return;const dt=last?Math.min((t-last)/1000,.04):0;last=t;if(!combatInit)initCombat();if(!paused){elapsed+=dt;duelClock+=dt;combatCooldown=Math.max(0,combatCooldown-dt);playerHurt=Math.max(0,playerHurt-dt);bossHurt=Math.max(0,bossHurt-dt);punchAge+=dt;damageTexts.forEach(d=>d.age+=dt);damageTexts=damageTexts.filter(d=>d.age<1.15);if(combatResult==='lost'){rescueTime+=dt;playRescueSong();if(rescueTime>=25){finish();return}}else{if(pendingPunch){pendingPunch.remaining-=dt;if(pendingPunch.remaining<=0){pendingPunch=null;hurtBoss();if(combatResult==='win'){draw();raf=requestAnimationFrame(frame);return}}}combatTimer-=dt;if(duelPhase==='strike'){bossAttackAge+=dt;if(bossAttackAge>=.16)hurtPlayer()}if(combatResult==='fight'&&combatTimer<=0){if(duelPhase==='intro'||duelPhase==='recover'){duelPhase='windup';combatTimer=1.4;attackLanded=false;toast('Boss lấy đà — bấm Né hoặc Đỡ!',1.4)}else if(duelPhase==='windup'){duelPhase='strike';combatTimer=.45;bossAttackAge=0;attackLanded=false}else if(duelPhase==='strike'){duelPhase='open';combatTimer=2.4;toast('SƠ HỞ! Đánh lúc này gây −25.',2.2)}else{duelPhase='recover';combatTimer=.65}}}if(elapsed>toastUntil)$('bubble').hidden=true}if(noiseGain)noiseGain.gain.value=0;draw();$('distance').textContent=`VY ${playerHP}/100 · BOSS ${duelHP}/100`;$('threat').textContent=combatResult==='lost'?'ĐỒNG ĐỘI ĐANG TỚI TIẾP TẾ':`MÁ SƯNG ${cheekLevel}/3 · ${duelPhase==='open'?'PHẢN CÔNG −25':'ĐÁNH THƯỜNG −10'}`;$('action').textContent=combatResult==='lost'?'Xem tiếp ♥':duelPhase==='open'?'Phản công −25':'Đánh −10';$('action').disabled=paused||(combatResult==='fight'&&(combatCooldown>0||duelPhase==='intro'));raf=requestAnimationFrame(frame)};
draw=function(){if(mode!==2||lateEnding>=0||combatResult==='win'){beforeCombatDraw();return}if(combatResult==='lost')drawRescue();else drawCombat()};
function combatSprite(punch,x,y,height){if(!combatReady){sprite(punch?3:2,x,y,height);return}const cw=combatSheet.width/4,sy=punch?combatSheet.height*.53:0,ch=combatSheet.height*(punch?.47:.53),width=height*cw/ch;ctx.drawImage(combatSheet,cheekLevel*cw,sy,cw,ch,x-width/2,y-height,width,height);if(cheekLevel>0&&playerHurt>0){ctx.save();ctx.globalAlpha=Math.min(.7,playerHurt*1.4);ctx.fillStyle='#ff5261';ctx.shadowColor='#ff6879';ctx.shadowBlur=8;ctx.beginPath();ctx.ellipse(x+width*.17,y-height*(punch?.57:.64),height*.033,height*.027,-.2,0,7);ctx.fill();ctx.restore()}}
function healthBar(x,y,w,hp,label,color){ctx.fillStyle='#0b1c2bdd';ctx.fillRect(x,y,w,9);ctx.fillStyle=color;ctx.fillRect(x,y,w*Math.max(0,hp)/100,9);text(`${label} · ${hp}/100`,x+w/2,y-10,11,color)}
function drawCombat(){const w=canvas.clientWidth,h=canvas.clientHeight,g=h*.8,size=Math.min(245,h*.44,w*.38);streetBackdrop(w,h);ctx.fillStyle='#07142299';ctx.fillRect(0,0,w,h);ctx.fillStyle='#233743';ctx.fillRect(0,g,w,h-g);ctx.strokeStyle='#d4b47c';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(0,g);ctx.lineTo(w,g);ctx.stroke();healthBar(w*.07,h*.15,w*.37,playerHP,'VY','#b5ded2');healthBar(w*.56,h*.15,w*.37,duelHP,'RĂNG KHÔN','#edbf7d');text('ĐẤU TRƯỜNG · ĐÒN THƯỜNG −10 / PHẢN CÔNG −25',w/2,h*.075,Math.max(8,Math.min(11,w/55)),'#dfc18d');
const punch=punchAge<.44,progress=Math.max(0,Math.min(1,punchAge/.44)),dash=punch?Math.sin(progress*Math.PI)*w*.32:0,dodge=duelClock<dodgeUntil?w*.10:0,hurtOffset=playerHurt>0?Math.sin(playerHurt*45)*7:0,px=w*.24+dash-dodge+hurtOffset;ctx.save();if(playerHurt>0)ctx.globalAlpha=.8;combatSprite(punch,px,g+10,size);ctx.restore();if(duelClock<guardUntil){ctx.strokeStyle='#b7f1e5';ctx.lineWidth=3;ctx.beginPath();ctx.arc(px+size*.21,g-size*.48,size*.29,-1.3,1.3);ctx.stroke()}
const bossLunge=duelPhase==='strike'?Math.sin(Math.min(1,bossAttackAge/.45)*Math.PI)*w*.30:0,bx=w*.75-bossLunge+(bossHurt>0?Math.sin(bossHurt*50)*10:0);bossPhase=duelPhase==='open'?'exposed':'warning';bossFlash=bossHurt;drawTooth(bx,g-50,Math.min(1.4,w/360));
if(punch&&punchAge>.13&&punchAge<.3){const cx=px+size*.30,cy=g-size*.47;ctx.strokeStyle='#fff0b5';ctx.lineWidth=3;for(let i=0;i<9;i++){const a=i*Math.PI*2/9;ctx.beginPath();ctx.moveTo(cx+Math.cos(a)*7,cy+Math.sin(a)*7);ctx.lineTo(cx+Math.cos(a)*22,cy+Math.sin(a)*22);ctx.stroke()}}for(const d of damageTexts){const x=d.side==='boss'?w*.74:w*.25;ctx.globalAlpha=Math.max(0,1-d.age/1.15);text(d.text,x,h*.40-d.age*38,Math.max(12,Math.min(21,w*.025)),d.color);ctx.globalAlpha=1}
const caption=duelPhase==='intro'?'Sẵn sàng!':duelPhase==='windup'?'Boss lấy đà — NÉ hoặc ĐỠ':duelPhase==='strike'?'ĐÒN TẤN CÔNG!':duelPhase==='open'?'BOSS SƠ HỞ · PHẢN CÔNG −25':'Đánh thường vẫn gây −10 sát thương';text(caption,w/2,h*.92,Math.max(9,Math.min(13,w/42)),duelPhase==='open'?'#ffe3a3':'#d1dbd8');if(playerHurt>.3){ctx.fillStyle='#e86f6822';ctx.fillRect(0,0,w,h)}}
function playRescueSong(){if(rescueTime<9)return;const st=rescueTime-9;for(let i=rescueNote+1;i<birthdayNotes.length;i++){if(st<birthdayNotes[i][0])break;rescueNote=i;beep(birthdayNotes[i][1],birthdayNotes[i][2])}}
function drawRescue(){const w=canvas.clientWidth,h=canvas.clientHeight,t=rescueTime,g=h*.84;let caption='';if(t<5){streetBackdrop(w,h);ctx.fillStyle='#07142288';ctx.fillRect(0,0,w,h);sprite(5,w*.32,g,Math.min(235,h*.44));drawTooth(w*.75+(t/5)*w*.3,g-55,Math.min(1.3,w/350));caption=t<2?'Răng khôn thắng hiệp này.':'Vy được quyền nghỉ một chút.'}else{if(officeReady){const r=Math.max(w/officeScene.width,h/officeScene.height);ctx.drawImage(officeScene,(w-officeScene.width*r)/2,(h-officeScene.height*r)/2,officeScene.width*r,officeScene.height*r)}else streetBackdrop(w,h);ctx.fillStyle='#805a2722';ctx.fillRect(0,0,w,h);lifeSprite(4,w*.23,g,Math.min(230,h*.43));caption=t<9?'Trạm tiếp tế xin báo: không thắng boss cũng không mất phần sinh nhật.':t<20?'♪ Chúc mừng sinh nhật Vy! Đồng đội mang bánh tới rồi. ♪':'Hôm nay không cần mạnh mẽ thêm nữa. Cứ nhận yêu thương thôi.';if(t>=8){const offset=(1-Math.min(1,(t-8)/2))*w*.7;lifeSprite(5,w*.44+offset,g+10,Math.min(225,h*.42));lifeSprite(6,w*.61+offset,g,Math.min(210,h*.40));lifeSprite(7,w*.82+offset,g,Math.min(215,h*.40));for(let i=0;i<8;i++)text(i%2?'♪':'♫',w*(.4+i*.06),g-150-((t*20+i*17)%60),15,'#ffdfa0')}}ctx.fillStyle='#0b192be8';ctx.fillRect(0,0,w,h*.18);text('THUA HIỆP ĐẤU · KHÔNG MẤT PHẦN SINH NHẬT',w/2,h*.07,Math.max(9,Math.min(14,w/48)),'#e9c58a');text(caption,w/2,h*.135,Math.max(8,Math.min(12,w/62)),'#f0e0c8')}
finish=function(){beforeCombatFinish();if(combatResult==='lost'&&endingKind==='boss-rest'){retryBossButton.hidden=false;const label=$('finish').querySelector('.eyebrow');if(label)label.textContent='TEAM RESCUE / SINH NHẬT VẪN DÀNH CHO VY';const lead=$('finish').querySelector('.lead');if(lead)lead.innerHTML='Không cần thắng mọi trận đấu,<br>Vy vẫn xứng đáng có một sinh nhật thật vui.'}};
